import { test, ok } from 'node:test';
import { strict as assert } from 'node:assert';

import { capitalize } from '../src/capitalize.mjs';

test('capitalize multi-word', () => {
  assert.strictEqual(capitalize('hello world'), 'Hello World');
});

test('capitalize empty string', () => {
  assert.strictEqual(capitalize(''), '');
});

test('capitalize mixed-case', () => {
  assert.strictEqual(capitalize('hELLo wOrld'), 'Hello World');
});

test('capitalize single word', () => {
  assert.strictEqual(capitalize('hello'), 'Hello');
});

